function normalizeObject(object,targetSize=1.55){object.updateMatrixWorld(true);const box=new THREE.Box3().setFromObject(object);if(box.isEmpty())return object;const size=new THREE.Vector3(),center=new THREE.Vector3();box.getSize(size);box.getCenter(center);object.scale.multiplyScalar(targetSize/(Math.max(size.x,size.y,size.z)||1));object.updateMatrixWorld(true);const box2=new THREE.Box3().setFromObject(object);box2.getCenter(center);object.position.x-=center.x;object.position.z-=center.z;object.position.y-=box2.min.y;return object}
