function disposeObject(o){o.traverse?.(n=>{n.geometry?.dispose?.();if(n.material)(Array.isArray(n.material)?n.material:[n.material]).forEach(m=>m.dispose?.())})}
async function loadSportModel(s){const group=groupsById.get(s.id);if(!group||group.userData.loading||group.userData.modelSource==='real')return;group.userData.loading=true;try{const url=s.modelUrl||await resolve3DAsset(s.modelSearch);if(!url)throw new Error('No matching model');const loader=gltfLoader;const gltf=await new Promise((resolve,reject)=>loader.load(url,resolve,undefined,reject)),model=gltf.scene||gltf.scenes?.[0];if(!model)throw new Error('GLB contains no scene');model.traverse(n=>{if(n.isMesh){n.castShadow=false;n.receiveShadow=false}});normalizeObject(model,1.6);const content=group.getObjectByName('content');clearGroup(content);content.add(model);group.userData.modelSource='real';group.userData.modelUrl=url;group.userData.loaded=true;modelCache.set(s.id,{url});if(gltf.animations?.length){const mixer=new THREE.AnimationMixer(model);mixer.clipAction(gltf.animations[0]).play();group.userData.mixer=mixer}if(currentSport?.id===s.id)updateModelStatus(group)}catch(err){console.warn(`3D model fallback: ${s.name}`,err);setProceduralFallback(group,s,'failed');if(currentSport?.id===s.id)updateModelStatus(group)}finally{group.userData.loading=false;labelsDirty=true}}
async function resolve3DAsset(query){if(assetSearchCache.has(query))return assetSearchCache.get(query);try{const u='https://3dassets.dev/api/v1/assets?'+new URLSearchParams({q:query,sort:'relevance',limit:'8'}),r=await fetch(u,{mode:'cors'});if(!r.ok)throw new Error(`asset search ${r.status}`);const j=await r.json();let list=Array.isArray(j)?j:Array.isArray(j.assets)?j.assets:Array.isArray(j.items)?j.items:Array.isArray(j.results)?j.results:Array.isArray(j.data)?j.data:Array.isArray(j.data?.assets)?j.data.assets:[];const tokens=query.toLowerCase().split(/\s+/).filter(x=>x.length>2);list.sort((a,b)=>scoreAsset(b,tokens)-scoreAsset(a,tokens));const url=list.map(assetCdnUrl).find(Boolean)||null;assetSearchCache.set(query,url);return url}catch(e){console.warn('3DAssets search failed:',query,e);assetSearchCache.set(query,null);return null}}
function scoreAsset(a,tokens){const text=`${a.title||a.name||''} ${a.summary||a.description||''}`.toLowerCase();return tokens.reduce((n,t)=>n+(text.includes(t)?2:0),0)-(a.stats?.triangles>80000?2:0)}
function assetCdnUrl(a){return a?.cdnUrl||a?.cdn_url||a?.modelUrl||a?.model_url||a?.file?.cdnUrl||a?.files?.model?.cdnUrl||a?.download?.cdnUrl||null}
