function buildSymbolStrip(){const strip=$('#sport-symbol-strip');strip.innerHTML=SPORTS.map(s=>`<button class="sport-symbol" type="button" data-sport="${s.id}" data-cat="${s.category}" aria-label="Open ${escapeHtml(s.name)}"><span class="symbol-icon">${s.icon}</span><span class="symbol-name">${escapeHtml(s.name)}</span></button>`).join('');strip.addEventListener('click',e=>{const b=e.target.closest('.sport-symbol');if(b)selectSport(groupsById.get(b.dataset.sport))})}
function bindUI(){addEventListener('resize',onResize,{passive:true});renderer.domElement.addEventListener('pointermove',onPointerMove,{passive:true});renderer.domElement.addEventListener('pointerdown',onPointerDown);renderer.domElement.addEventListener('pointerup',onPointerUp,{passive:true});renderer.domElement.addEventListener('pointercancel',onPointerUp,{passive:true});renderer.domElement.addEventListener('wheel',()=>labelsDirty=true,{passive:true});renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();paused=true;$('#context-recovery').hidden=false});renderer.domElement.addEventListener('webglcontextrestored',()=>{paused=false;$('#context-recovery').hidden=true;labelsDirty=true;animate()});document.addEventListener('visibilitychange',()=>{paused=document.hidden;if(!paused){clock.getDelta();labelsDirty=true;animate()}});$('#enter-arena').onclick=endIntro;$('#skip-intro').onclick=endIntro;$('#open-search').onclick=()=>openOverlay('search');$('#close-search').onclick=()=>openOverlay();$('#help-toggle').onclick=()=>openOverlay('help');$('#close-help').onclick=()=>openOverlay();$('#close-detail').onclick=backToHall;$('#back-btn').onclick=backToHall;$('#sound-toggle').onclick=toggleSound;$$('.category-chip').forEach(b=>b.onclick=()=>filterCategory(b.dataset.category));$$('.tab').forEach(b=>b.onclick=()=>{currentTab=b.dataset.tab;$$('.tab').forEach(x=>x.classList.toggle('active',x===b));renderTab()});$('#search-input').addEventListener('input',renderSearch);renderSearch();$('#lightbox-close').onclick=closeLightbox;$('#lightbox-prev').onclick=()=>stepLightbox(-1);$('#lightbox-next').onclick=()=>stepLightbox(1);$('#lightbox').addEventListener('click',e=>{if(e.target.id==='lightbox')closeLightbox()});$('#model-viewer-close').onclick=closeEquipmentViewer;$('#model-viewer').addEventListener('click',e=>{if(e.target.id==='model-viewer')closeEquipmentViewer()});$('#viewer-reset').onclick=()=>viewer?.reset?.();addEventListener('keydown',e=>{if(e.key==='Escape'){if($('#model-viewer').classList.contains('open'))closeEquipmentViewer();else if($('#lightbox').classList.contains('open'))closeLightbox();else if(currentSport)backToHall();else openOverlay()}if(e.key==='ArrowLeft'&&$('#lightbox').classList.contains('open'))stepLightbox(-1);if(e.key==='ArrowRight'&&$('#lightbox').classList.contains('open'))stepLightbox(1);if(e.key==='/'&&!e.metaKey&&!e.ctrlKey){e.preventDefault();openOverlay('search')}})}
