async function preloadRemainingModels(){const queue=SPORTS.filter(s=>!groupsById.get(s.id)?.userData.loaded&&!groupsById.get(s.id)?.userData.loading);for(let i=0;i<queue.length;i++){if(document.hidden)await wait(500);await loadSportModel(queue[i]);if(i%2===1)await idle(80)}}
