let dragInspect=false,lastX=0,lastY=0,moved=false;
function updatePointer(e){const rect=renderer.domElement.getBoundingClientRect();pointer.x=((e.clientX-rect.left)/rect.width)*2-1;pointer.y=-((e.clientY-rect.top)/rect.height)*2+1}
function onPointerMove(e){updatePointer(e);$('#pointer-label').style.left=e.clientX+'px';$('#pointer-label').style.top=e.clientY+'px';if(currentSport&&dragInspect&&selectedGroup){const dx=e.clientX-lastX,dy=e.clientY-lastY;if(Math.abs(dx)+Math.abs(dy)>2)moved=true;const content=selectedGroup.getObjectByName('content');content.rotation.y+=dx*.008;content.rotation.x=THREE.MathUtils.clamp(content.rotation.x+dy*.003,-.35,.35);lastX=e.clientX;lastY=e.clientY;return}if(pointerRaf)return;pointerRaf=requestAnimationFrame(()=>{pointerRaf=0;raycastHover()})}
