function onPointerUp(){if(currentSport){dragInspect=false;return}const hit=raycastNow();if(hit&&!moved)selectSport(hit.userData.parentSport)}
function raycastNow(){raycaster.setFromCamera(pointer,camera);return raycaster.intersectObjects(interactive,false).map(h=>h.object).find(o=>o.userData.parentSport?.visible&&!o.userData.parentSport.userData.filtered)||null}
