function hoverTo(hit){if(hoverHit===hit)return;if(hoverHit)hoverHit.userData.parentSport.userData.label?.classList.remove('active');hoverHit=hit;if(hit){const g=hit.userData.parentSport;g.userData.label?.classList.add('active');$('#pointer-label').hidden=coarsePointer;$('#pointer-label').textContent=g.userData.sport.name.toUpperCase();document.body.style.cursor='pointer';animateSportPulse(g)}else{$('#pointer-label').hidden=true;document.body.style.cursor='default'}}
function animateSportPulse(g){const c=g.getObjectByName('content');if(!c)return;const start=performance.now(),base=c.scale.x;function tick(now){const t=Math.min(1,(now-start)/180),s=base+Math.sin(t*Math.PI)*.08;c.scale.setScalar(s);if(t<1)requestAnimationFrame(tick);else c.scale.setScalar(base)}requestAnimationFrame(tick)}
function selectSport(group){if(!group)return;currentSport=group.userData.sport;selectedGroup=group;hoverTo(null);playUi(.04,520);$('#hero-hud').classList.add('hidden');$('#sport-symbol-strip').classList.add('is-hidden');$('#detail-panel').classList.add('open');$('#detail-panel').setAttribute('aria-hidden','false');$('#detail-category').textContent=(CATEGORY_LABELS[currentSport.category]||currentSport.category.toUpperCase())+' SPORT';$('#detail-name').textContent=currentSport.name.toUpperCase();currentTab='overview';$$('.tab').forEach(x=>x.classList.toggle('active',x.dataset.tab==='overview'));renderTab();updateModelStatus(group);SPORTS.forEach(s=>{const g=groupsById.get(s.id);if(g!==group){g.visible=false;g.userData.label.classList.add('filtered')}});group.visible=true;group.userData.label.classList.remove('filtered');setModelShadows(group,true);const p=group.position.clone(),dir=p.clone().normalize(),dest=p.clone().add(dir.multiplyScalar(mobile?5.7:5.15)).add(new THREE.Vector3(0,mobile?2:2.55,0));startCameraTween(dest,p.clone().add(new THREE.Vector3(0,.3,0)),reducedMotion?140:650);controls.enabled=false;labelsDirty=true;if(group.userData.modelSource!=='real'&&!group.userData.loading)loadSportModel(currentSport)}
function backToHall(){if(!currentSport)return;playUi(.025,180);setModelShadows(selectedGroup,false);currentSport=null;selectedGroup=null;$('#detail-panel').classList.remove('open');$('#detail-panel').setAttribute('aria-hidden','true');$('#hero-hud').classList.remove('hidden');$('#sport-symbol-strip').classList.remove('is-hidden');SPORTS.forEach(s=>{const g=groupsById.get(s.id),ok=activeCategory==='All'||s.category===activeCategory;g.visible=ok;g.userData.label.classList.toggle('filtered',!ok)});startCameraTween(new THREE.Vector3(0,8.4,16.4),new THREE.Vector3(0,1.1,0),reducedMotion?120:620,()=>controls.enabled=true);labelsDirty=true}
