function updateCameraTween(now){if(!cameraTween)return;const t=Math.min(1,(now-cameraTween.start)/cameraTween.duration),k=1-Math.pow(1-t,3);camera.position.lerpVectors(cameraTween.fromP,cameraTween.toP,k);controls.target.lerpVectors(cameraTween.fromT,cameraTween.toT,k);labelsDirty=true;if(t>=1){const done=cameraTween.onDone;cameraTween=null;done?.()}}
function updateModelStatus(g){const src=g.userData.modelSource;$('#model-status').innerHTML=`<i></i> ${src==='real'?'REAL GLB / CC0':src==='procedural fallback'?'PROCEDURAL FALLBACK':'LOADING 3D ASSET'}`}
function renderTab(){if(!currentSport)return;const s=currentSport,c=$('#tab-content');if(currentTab==='overview'){c.innerHTML=`<p class="panel-copy">${escapeHtml(s.overview)}</p><div class="info-stats"><div class="stat"><b>${escapeHtml(s.players)}</b><span>PLAYERS</span></div><div class="stat"><b>${escapeHtml(s.place)}</b><span>ARENA</span></div><div class="stat"><b>${escapeHtml(s.scoring)}</b><span>SCORING</span></div></div><div class="photo-card"><img data-query="${escapeAttr(s.name+' sport competition')}" alt="${escapeAttr(s.name+' real-world sport scene')}" src="${realPhotoFallback(s.name+' sport competition')}"><span>REAL WORLD / ${escapeHtml(s.name.toUpperCase())}</span></div><p class="panel-copy">The 3D display uses a web-optimized CC0 asset when a matching model is available, with a sport-specific procedural fallback only when the asset cannot be loaded.</p>`;hydrateImages(c)}else if(currentTab==='equipment'){c.innerHTML=`<p class="panel-copy">Each item loads a sport-specific real-world visual on demand. Use the inspector for a separate rotatable 3D view.</p><div class="visual-grid">${s.equipment.map((x,i)=>visualCard(s,x,'equipment',i,true)).join('')}</div>`;hydrateImages(c);bindViewerButtons(c,s)}else if(currentTab==='clothing'){c.innerHTML=`<p class="panel-copy">Clothing and protective apparel vary with movement, climate, impact risk and surface.</p><div class="visual-grid">${s.clothing.map((x,i)=>visualCard(s,x,'clothing',i,false)).join('')}</div>`;hydrateImages(c)}else if(currentTab==='rules')c.innerHTML=`<ul class="list-clean">${s.rules.map(x=>`<li>${escapeHtml(x)}</li>`).join('')}</ul>`;else if(currentTab==='skills')c.innerHTML=`<div class="item-grid">${s.skills.map(x=>`<div class="item"><b>${escapeHtml(x)}</b><span>Core performance skill</span></div>`).join('')}</div>`;else if(currentTab==='facts')c.innerHTML=`<ul class="list-clean">${s.facts.map(x=>`<li>${escapeHtml(x)}</li>`).join('')}</ul>`;else renderGallery(c,s)}
function visualCard(s,item,type,i,with3D){const query=`${s.name} ${item} ${type==='clothing'?'sportswear equipment':'sports equipment'}`;return `<article class="visual-card"><div class="visual-card-media"><img data-query="${escapeAttr(query)}" src="${realPhotoFallback(query)}" alt="${escapeAttr(item)}"><span class="image-credit">Loading free-media visual…</span></div><div class="visual-card-body"><b>${escapeHtml(item)}</b><p>${escapeHtml(type==='clothing'?wearPurpose(item,s.name):equipmentPurpose(item,s.name))}</p>${with3D?`<button class="view3d" data-item="${escapeAttr(item)}">VIEW IN 3D</button>`:''}</div></article>`}
function equipmentPurpose(x,s){const v=x.toLowerCase();if(v.includes('helmet'))return'Protective headgear designed to manage impact and sport-specific hazards.';if(v.includes('glove'))return'Improves protection, grip or control while matching the movement demands of the sport.';if(v.includes('shoe')||v.includes('boot')||v.includes('cleat'))return'Provides traction, stability and efficient force transfer on the sport’s surface.';if(v.includes('racket')||v.includes('paddle'))return'Primary striking tool used to control speed, placement and spin.';if(v.includes('ball')||v.includes('puck')||v.includes('shuttle'))return`Primary object used to create scoring actions in ${s}.`;if(v.includes('net')||v.includes('goal')||v.includes('ring'))return'Defines a central scoring, boundary or target structure for play.';return`${x} supports performance, control, training or safety in ${s}.`}
function wearPurpose(x,s){const v=x.toLowerCase();if(/shoe|boot|cleat/.test(v))return'Sport-specific footwear for traction, stability and movement efficiency.';if(/helmet|goggle|pad|guard/.test(v))return'Protective apparel designed to reduce exposure to sport-specific hazards.';return`Athletic apparel shaped around the movement and environmental demands of ${s}.`}
async function hydrateImages(root){for(const img of root.querySelectorAll('img[data-query]')){const query=img.dataset.query;commonsImage(query).then(info=>{if(!info||!img.isConnected)return;img.src=info.src;img.onerror=()=>{img.onerror=null;img.src=realPhotoFallback(query)};const credit=img.parentElement?.querySelector('.image-credit');if(credit){credit.textContent=info.credit;credit.title=info.credit}})}}
async function commonsImage(query,width=900){const key=query+'|'+width;if(imageCache.has(key))return imageCache.get(key);try{const params=new URLSearchParams({action:'query',format:'json',origin:'*',generator:'search',gsrsearch:query,gsrnamespace:'6',gsrlimit:'8',prop:'imageinfo',iiprop:'url|extmetadata|mime',iiurlwidth:String(width)}),r=await fetch('https://commons.wikimedia.org/w/api.php?'+params);if(!r.ok)throw new Error(r.status);const j=await r.json(),pages=Object.values(j.query?.pages||{}),candidates=pages.map(p=>({p,ii:p.imageinfo?.[0]})).filter(x=>x.ii?.thumburl&&x.ii.mime?.startsWith('image/'));if(!candidates.length)throw new Error('no image');const {p,ii}=candidates[0],meta=ii.extmetadata||{},artist=stripTags(meta.Artist?.value||meta.Credit?.value||'Wikimedia Commons'),license=stripTags(meta.LicenseShortName?.value||'free media'),info={src:ii.thumburl,full:ii.url||ii.thumburl,credit:`${artist} · ${license}`,page:p.pageid?`https://commons.wikimedia.org/?curid=${p.pageid}`:''};imageCache.set(key,info);return info}catch(e){console.warn('Commons image fallback:',query,e);const photo=realPhotoFallback(query,width,Math.round(width*.72)),info={src:photo,full:photo,credit:'Creative Commons photo · LoremFlickr / Flickr'};imageCache.set(key,info);return info}}
function stripTags(s){const d=document.createElement('div');d.innerHTML=s;return(d.textContent||'').replace(/\s+/g,' ').trim().slice(0,90)}
function realPhotoFallback(query,width=900,height=650){const stop=new Set(['sport','sports','equipment','sportswear','competition','real','world','athlete','action']);const tags=String(query).toLowerCase().replace(/[^a-z0-9\\s-]/g,' ').split(/\\s+/).filter(Boolean).filter(x=>!stop.has(x)).slice(0,5);if(!tags.length)tags.push('sports');let h=17;for(const ch of String(query))h=((h*31)+ch.charCodeAt(0))>>>0;const lock=h%99991+1;return`https://loremflickr.com/${width}/${height}/${encodeURIComponent(tags.join(','))}?lock=${lock}`}
function fallbackImage(label,icon='SS'){const safe=String(label).replace(/[<>&"']/g,'').slice(0,36),ico=String(icon).replace(/[<>&"']/g,'').slice(0,4);return`data:image/svg+xml;charset=UTF-8,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="900" height="650"><defs><radialGradient id="g"><stop stop-color="#263544"/><stop offset="1" stop-color="#080b0f"/></radialGradient></defs><rect width="100%" height="100%" fill="url(#g)"/><circle cx="450" cy="280" r="120" fill="none" stroke="#78f000" stroke-opacity=".25" stroke-width="3"/><text x="450" y="300" text-anchor="middle" font-family="Arial" font-size="78" fill="#fff">${ico}</text><text x="450" y="470" text-anchor="middle" font-family="Arial" font-weight="700" font-size="32" fill="#dce4ea">${safe}</text><text x="450" y="520" text-anchor="middle" font-family="Arial" font-size="15" letter-spacing="4" fill="#74808a">SAEID SPORTS</text></svg>`)}`}
function renderGallery(c,s){const defs=[['ACTION',`${s.name} sport athlete action`],['VENUE',`${s.name} sport venue competition`],['EQUIPMENT',`${s.name} sports equipment`],['TRAINING',`${s.name} sport training`]];c.innerHTML=`<p class="panel-copy">Real-world free-media references. Select an image for fullscreen view.</p><div class="gallery-grid">${defs.map((d,i)=>`<button class="gallery-tile" data-index="${i}"><img src="${fallbackImage(d[0],s.icon)}" alt="${escapeAttr(s.name+' '+d[0])}"><span>${d[0]}</span></button>`).join('')}</div>`;galleryImages=defs.map(d=>({src:fallbackImage(d[0],s.icon),full:fallbackImage(d[0],s.icon),alt:`${s.name} ${d[0]}`}));defs.forEach(async(d,i)=>{const info=await commonsImage(d[1],1200);galleryImages[i]={src:info.src,full:info.full||info.src,alt:`${s.name} ${d[0]}`,credit:info.credit};const img=c.querySelector(`.gallery-tile[data-index="${i}"] img`);if(img?.isConnected)img.src=info.src});c.querySelectorAll('.gallery-tile').forEach(b=>b.onclick=()=>openLightbox(Number(b.dataset.index)))}
function openLightbox(i){galleryIndex=i;updateLightbox();$('#lightbox').classList.add('open');$('#lightbox').setAttribute('aria-hidden','false')}function updateLightbox(){const item=galleryImages[galleryIndex];if(item){$('#lightbox-image').src=item.full||item.src;$('#lightbox-image').alt=item.alt||''}}function stepLightbox(dir){if(galleryImages.length){galleryIndex=(galleryIndex+dir+galleryImages.length)%galleryImages.length;updateLightbox()}}function closeLightbox(){$('#lightbox').classList.remove('open');$('#lightbox').setAttribute('aria-hidden','true')}
function bindViewerButtons(root,s){root.querySelectorAll('.view3d').forEach(b=>b.onclick=()=>openEquipmentViewer(s,b.dataset.item))}
async function openEquipmentViewer(s,item){const modal=$('#model-viewer');modal.classList.add('open');modal.setAttribute('aria-hidden','false');$('#viewer-title').textContent=item.toUpperCase();$('#viewer-status').textContent='LOADING CC0 MODEL…';initViewer();viewer.clear();const exactMap={'Tennis Racket':'https://cdn.3dassets.dev/assets/33614/v1/model.glb','Racing Helmet':'https://cdn.3dassets.dev/assets/15435/v1/model.glb','Hockey Stick':'https://cdn.3dassets.dev/assets/33716/v1/model.glb','Bicycle':'https://cdn.3dassets.dev/assets/38014/v1/model.glb'};try{const url=exactMap[item]||await resolve3DAsset(`${s.name} ${item}`);if(!url)throw new Error('no item model');const gltf=await new Promise((res,rej)=>gltfLoader.load(url,res,undefined,rej)),model=gltf.scene;normalizeObject(model,2.4);viewer.add(model);$('#viewer-status').textContent='REAL GLB · CC0 · DRAG / PINCH / ZOOM'}catch(e){const fallback=buildEquipmentFallback(item,s);viewer.add(fallback);$('#viewer-status').textContent='PROCEDURAL FALLBACK · MODEL SOURCE UNAVAILABLE'}}
function buildEquipmentFallback(item,s){return buildIcon({...s,kind:guessKind(item,s.kind)})}function guessKind(item,def){const v=item.toLowerCase();if(v.includes('racket'))return'racket';if(v.includes('paddle'))return'paddle';if(v.includes('glove'))return'gloves';if(v.includes('helmet'))return'helmet';if(v.includes('shoe')||v.includes('boot'))return'shoe';if(v.includes('barbell'))return'barbell';if(v.includes('dumbbell'))return'dumbbell';if(v.includes('hockey'))return'hockey';if(v.includes('skateboard'))return'skate';if(v.includes('surfboard'))return'surf';if(v.includes('bow'))return'bow';if(v.includes('ski'))return'ski';return def}
function initViewer(){if(viewer)return;const canvas=$('#equipment-canvas'),r=new THREE.WebGLRenderer({canvas,antialias:true,alpha:true,powerPreference:'high-performance'});r.setPixelRatio(Math.min(devicePixelRatio,1.35));r.outputColorSpace=THREE.SRGBColorSpace;r.toneMapping=THREE.ACESFilmicToneMapping;const sc=new THREE.Scene(),cam=new THREE.PerspectiveCamera(42,1,.1,50);cam.position.set(0,2.2,5.4);const ctl=new OrbitControls(cam,canvas);ctl.enableDamping=true;ctl.target.set(0,1,0);ctl.minDistance=2.5;ctl.maxDistance=9;sc.add(new THREE.HemisphereLight(0xc7dbef,0x101216,1.6));const dl=new THREE.DirectionalLight(0xffffff,3);dl.position.set(4,6,5);sc.add(dl);let obj=null,raf=0;const resize=()=>{const w=canvas.clientWidth||800,h=canvas.clientHeight||600;r.setSize(w,h,false);cam.aspect=w/h;cam.updateProjectionMatrix()},loop=()=>{if(!$('#model-viewer').classList.contains('open')){raf=0;return}resize();ctl.update();r.render(sc,cam);raf=requestAnimationFrame(loop)};viewer={add(o){obj=o;sc.add(o);resize();if(!raf)loop()},clear(){if(obj){sc.remove(obj);disposeObject(obj);obj=null}},reset(){cam.position.set(0,2.2,5.4);ctl.target.set(0,1,0);ctl.update()},stop(){if(raf){cancelAnimationFrame(raf);raf=0}}}}
function closeEquipmentViewer(){$('#model-viewer').classList.remove('open');$('#model-viewer').setAttribute('aria-hidden','true');viewer?.stop()}
function filterCategory(cat){activeCategory=cat;$$('.category-chip').forEach(b=>b.classList.toggle('active',b.dataset.category===cat));let count=0;SPORTS.forEach(s=>{const g=groupsById.get(s.id),show=cat==='All'||s.category===cat;if(show)count++;g.userData.filtered=!show;startFilterTransition(g,show);g.userData.label.classList.toggle('filtered',!show)});$('#sport-count').textContent=count;$$('.sport-symbol').forEach(b=>b.hidden=cat!=='All'&&b.dataset.cat!==cat);$('#sport-symbol-strip').scrollTo({left:0,behavior:reducedMotion?'auto':'smooth'});playUi(.016,280);labelsDirty=true;if(cat!=='All')SPORTS.filter(s=>s.category===cat).forEach(s=>{const g=groupsById.get(s.id);if(g.userData.modelSource!=='real'&&!g.userData.loading)loadSportModel(s)})}
function startFilterTransition(g,show){const now=performance.now(),from=show?.82:1,to=show?1:.82;g.visible=true;prepareOpacity(g,show?0:1);g.scale.setScalar(from);filterTweens.add({g,show,start:now,duration:reducedMotion?1:220,from,to})}
function prepareOpacity(g,value){g.traverse(n=>{if(n.userData.isHitbox)return;if(n.material){for(const m of(Array.isArray(n.material)?n.material:[n.material])){if(m.userData.baseOpacity==null)m.userData.baseOpacity=m.opacity??1;m.transparent=true;m.opacity=m.userData.baseOpacity*value}}})}
function updateFilterTweens(now){if(!filterTweens.size)return;for(const tw of[...filterTweens]){const t=Math.min(1,(now-tw.start)/tw.duration),k=1-Math.pow(1-t,2),alpha=tw.show?k:1-k,s=THREE.MathUtils.lerp(tw.from,tw.to,k);tw.g.scale.setScalar(s);tw.g.traverse(n=>{if(n.userData.isHitbox)return;if(n.material){for(const m of(Array.isArray(n.material)?n.material:[n.material]))m.opacity=(m.userData.baseOpacity??1)*alpha}});if(t>=1){filterTweens.delete(tw);if(!tw.show)tw.g.visible=false;else prepareOpacity(tw.g,1)}}}
function openOverlay(which){const sp=$('#search-panel'),hp=$('#help-panel');sp.classList.toggle('open',which==='search');hp.classList.toggle('open',which==='help');sp.setAttribute('aria-hidden',which==='search'?'false':'true');hp.setAttribute('aria-hidden',which==='help'?'false':'true');if(which==='search')setTimeout(()=>$('#search-input').focus(),120)}
function renderSearch(){const q=$('#search-input').value.trim().toLowerCase(),list=SPORTS.filter(s=>!q||s.name.toLowerCase().includes(q)||s.category.toLowerCase().includes(q));$('#search-results').innerHTML=list.map(s=>`<button class="search-result" data-name="${s.id}"><span><b>${escapeHtml(s.name)}</b><small>${escapeHtml(CATEGORY_LABELS[s.category]||s.category.toUpperCase())}</small></span><i>↗</i></button>`).join('');$$('.search-result').forEach(b=>b.onclick=()=>{openOverlay();selectSport(groupsById.get(b.dataset.name));$('#search-input').value='';renderSearch()})}
function toggleSound(){soundOn=!soundOn;$('#sound-toggle').textContent=soundOn?'◉':'◕';$('#sound-toggle').setAttribute('aria-label',soundOn?'Mute sound':'Enable sound');if(soundOn){audioCtx??=new(window.AudioContext||window.webkitAudioContext)();playUi(.03,620)}}
function playUi(vol=.02,f=360){if(!soundOn)return;audioCtx??=new(window.AudioContext||window.webkitAudioContext)();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.setValueAtTime(f,audioCtx.currentTime);o.frequency.exponentialRampToValueAtTime(f*.74,audioCtx.currentTime+.08);g.gain.setValueAtTime(vol,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.0001,audioCtx.currentTime+.1);o.connect(g).connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+.11)}
function updateLabels(){labelsDirty=false;const w=innerWidth,h=innerHeight,tmp=new THREE.Vector3();SPORTS.forEach(s=>{const g=groupsById.get(s.id),el=g.userData.label;if(!g.visible||g.userData.filtered){el.style.opacity='0';return}tmp.copy(g.position);tmp.y+=2.25;tmp.project(camera);if(tmp.z>1||tmp.z<-1){el.style.opacity='0';return}const x=(tmp.x*.5+.5)*w,y=(-tmp.y*.5+.5)*h;el.style.left=x+'px';el.style.top=y+'px';el.style.opacity=(x<45||x>w-45||y<65||y>h-35)?'0':'1'})}
function onResize(){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,innerWidth<=900?1.1:1.5));labelsDirty=true}
let animating=false,lastFrame=0;function animate(){if(animating||paused||document.hidden)return;animating=true;const loop=time=>{if(paused||document.hidden){animating=false;return}requestAnimationFrame(loop);const minGap=mobile?20:0;if(minGap&&time-lastFrame<minGap)return;lastFrame=time;const dt=Math.min(clock.getDelta(),.05);updateCameraTween(time);updateFilterTweens(time);centerAthleteMixer?.update(dt);if(centerAthleteGroup&&!reducedMotion){centerAthleteGroup.rotation.y=Math.sin(time*.00045)*.09;centerAthleteGroup.position.y=.31+Math.sin(time*.0015)*.018}if(selectedGroup?.userData.mixer)selectedGroup.userData.mixer.update(dt);if(!reducedMotion&&particles)particles.rotation.y+=dt*.006;controls.update();if(labelsDirty)updateLabels();renderer.render(scene,camera)};requestAnimationFrame(loop)}
function logPerformanceLater(){setTimeout(()=>{if(renderer)console.info('[SAEID SPORTS perf]',{drawCalls:renderer.info.render.calls,triangles:renderer.info.render.triangles,geometries:renderer.info.memory.geometries,textures:renderer.info.memory.textures,pixelRatio:renderer.getPixelRatio(),sports:SPORTS.length})},6000)}
function escapeHtml(v){return String(v).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[ch]))}function escapeAttr(v){return escapeHtml(v)}

